   traps={'C2': [('=RATE(C3,C4,12000,C6)', 'ה-pv הוא מה שהמוצר שווה היום: 10,800 במזומן, ולא סכום התשלומים.')]},
   inotes={'C5': '<b>ערך נוכחי (pv):</b> כותבים ' + XL('10800') + '. המקרר שמקבלים היום שווה 10,800 במזומן. זה ״הסכום שלווים״, ולכן בפלוס.',
           'C6': '<b>ערך עתידי (fv):</b> כותבים ' + XL('0') + '. אחרי התשלום ה-12 לא חייבים כלום.'},
   steps=[dict(cells={'C2': '=RATE(C3,C4,C5,C6)'}, note='<b>נדרש א:</b> =RATE(C3,C4,C5,C6) נותן 1.6594% לחודש.'),
          dict(cells={'C7': '=(1+C2)^12-1'}, note='<b>נדרש ב:</b> =(1+C2)^12-1 נותן 21.83% לשנה. ״ללא ריבית״ עולה כמו כרטיס אשראי.')],
   note=[('tip', 'כשיש הנחה במזומן, ״ללא ריבית״ אינו ללא ריבית. משווים תמיד למחיר במזומן.', 1)],
